export T="$TMPDIR"; cat > $T/analyze3.py <<'EOF'
import re, os

root = os.getcwd()
files = [l.strip() for l in open(os.environ['TMPDIR'] + '/timer_files.txt') if l.strip()]

def read(p):
    try:
        return open(os.path.join(root, p), errors='replace').read()
    except Exception:
        return ''

cb_map = {}
for f in files:
    text = read(f)
    if not text:
        continue
    # match setup_timer(&X.Y, cb, ...) or setup_timer(&X, cb, ...) or setup_timer(var, cb, ...)
    for m in re.finditer(r'\b(?:setup_timer|timer_setup)\s*\(([^;]*?)\)\s*;', text, re.S):
        args = m.group(1)
        first_comma = args.find(',')
        if first_comma < 0:
            continue
        first = args[:first_comma].strip()
        rest = args[first_comma+1:]
        second_comma = rest.find(',')
        if second_comma < 0:
            continue
        cb = rest[:second_comma].strip()
        if not re.fullmatch(r'[A-Za-z_][A-Za-z_0-9]*', cb):
            continue
        if cb in ('setup_timer', 'timer_setup'):
            continue
        # line number
        line = text[:m.start()].count('\n') + 1
        cb_map.setdefault((f, cb), []).append(line)

print("unique (file,callback):", len(cb_map))
with open(os.environ['TMPDIR'] + '/timer_callbacks3.txt', 'w') as out:
    for (f, cb), lns in sorted(cb_map.items()):
        out.write(f"{f}\t{cb}\t{','.join(map(str,sorted(set(lns))))}\n")
EOF
python3 $T/analyze3.py; wc -l $T/timer_callbacks3.txt; head -50 $T/timer_callbacks3.txt

export T="$TMPDIR"; cat > $T/analyze4.py <<'EOF'
import re, os, sys

root = os.getcwd()
entries = []
for l in open(os.environ['TMPDIR'] + '/timer_callbacks3.txt'):
    parts = l.rstrip('\n').split('\t')
    if len(parts) >= 3:
        f, cb, lns = parts[0], parts[1], parts[2]
        if cb == 'NULL':
            continue
        entries.append((f, cb, lns))

def read(p):
    try:
        return open(os.path.join(root, p), errors='replace').read().splitlines()
    except Exception:
        return []

# find function definition spans for each callback, then look for spin_lock inside
def find_def(lines, cb):
    # definition patterns
    pats = [
        re.compile(r'^\s*(?:static\s+)?(?:inline\s+)?(?:void|unsigned long|int|long|bool)\s+' + re.escape(cb) + r'\s*\('),
        re.compile(r'^\s*(?:static\s+)?[A-Za-z_][A-Za-z_0-9 \*]*\*' + re.escape(cb) + r'\s*\('),
    ]
    for i, ln in enumerate(lines):
        for p in pats:
            if p.search(ln):
                return i
    return None

def func_span(lines, start):
    # from start line, find first '{' then match braces
    depth = 0
    began = False
    for i in range(start, min(start+400, len(lines))):
        for ch in lines[i]:
            if ch == '{':
                depth += 1
                began = True
            elif ch == '}':
                depth -= 1
                if began and depth == 0:
                    return (start, i)
    return (start, min(start+399, len(lines)-1))

hits = []
for f, cb, lns in entries:
    lines = read(f)
    if not lines:
        continue
    d = find_def(lines, cb)
    if d is None:
        continue
    s, e = func_span(lines, d)
    body = '\n'.join(lines[s:e+1])
    locks = re.findall(r'spin_lock(?:_irqsave|_irq|_bh)?\s*\(\s*&?([A-Za-z_0-9\.\>\[\]\-]+)', body)
    if locks:
        hits.append((f, cb, lns, s+1, e+1, sorted(set(locks))))

print("callbacks containing spinlock acquisitions:", len(hits))
with open(os.environ['TMPDIR'] + '/timer_cb_with_locks.txt', 'w') as out:
    for f, cb, lns, s, e, locks in hits:
        out.write(f"{f}\t{cb}\treg@{lns}\tdef {s}-{e}\t{','.join(locks)}\n")
EOF
python3 $T/analyze4.py; cat $T/timer_cb_with_locks.txt

